SELECT ?film ?filmLabel ?director ?directorLabel ?birth WHERE {
  BIND(dbr:Bhoomiyude_Avakashikal AS ?filmA)
  BIND(dbr:The_Majesty_of_the_Law AS ?filmB)
  ?filmA dbo:director ?dirA .
  ?filmB dbo:director ?dirB .
  OPTIONAL { ?dirA dbo:birthDate ?bA1 }
  OPTIONAL { ?dirA dbp:birthDate ?bA2 }
  OPTIONAL { ?dirB dbo:birthDate ?bB1 }
  OPTIONAL { ?dirB dbp:birthDate ?bB2 }
  BIND(COALESCE(?bA1, ?bA2) AS ?birthA)
  BIND(COALESCE(?bB1, ?bB2) AS ?birthB)
  {
    FILTER(BOUND(?birthA) && BOUND(?birthB) && (?birthA > ?birthB))
    BIND(?filmA AS ?film)
    BIND(?dirA AS ?director)
    BIND(?birthA AS ?birth)
  }
  UNION
  {
    FILTER(BOUND(?birthA) && BOUND(?birthB) && (?birthB > ?birthA))
    BIND(?filmB AS ?film)
    BIND(?dirB AS ?director)
    BIND(?birthB AS ?birth)
  }
  OPTIONAL { ?film rdfs:label ?filmLabel FILTER (lang(?filmLabel) = 'en') }
  OPTIONAL { ?director rdfs:label ?directorLabel FILTER (lang(?directorLabel) = 'en') }
}

