PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
SELECT ?film ?filmLabel ?director ?directorLabel ?birth WHERE {
  VALUES ?film {
    dbr:Bhoomiyude_Avakashikal dbr:The_Majesty_of_the_Law
  }
  ?film dbo:director ?director .
  OPTIONAL {
    ?director dbo:birthDate ?birth1
  }
  OPTIONAL {
    ?director dbp:birthDate ?birth2
  }
  BIND(COALESCE(?birth1 , ?birth2) AS ?birth)
  OPTIONAL {
    ?film rdfs:label ?filmLabel
    FILTER(lang(?filmLabel) = 'en')
  }
  OPTIONAL {
    ?director rdfs:label ?directorLabel
    FILTER(lang(?directorLabel) = 'en')
  }
}
ORDER BY DESC(str(?birth))
LIMIT 1

